export function createAxisLabels(axis: Axis): {
    labels: {
        level?: number,
        formattedLabel: string,
        rawLabel: string,
        tickValue: number
    }[],
    labelCategoryInterval?: number
} {
    const custom = makeAxisLabelsFromCustomValues(axis);
    if (custom) {
        return custom;
    }
    // Only ordinal scale support tick interval
    return axis.type === 'category'
        ? makeCategoryLabels(axis)
        : makeRealNumberLabels(axis);
}

/**
 * @param {module:echats/coord/Axis} axis
 * @param {module:echarts/model/Model} tickModel For example, can be axisTick, splitLine, splitArea.
 * @return {Object} {
 *     ticks: Array.<number>
 *     tickCategoryInterval: number
 * }
 */
export function createAxisTicks(axis: Axis, tickModel: AxisBaseModel): {
    ticks: number[],
    tickCategoryInterval?: number
} {
    const customValues = (tickModel as unknown as Model<AxisTickOption>).get('customValues');
    if (customValues) {
        return { ticks: parseCustomValues(axis, customValues) };
    }
    // Only ordinal scale support tick interval
    return axis.type === 'category'
        ? makeCategoryTicks(axis, tickModel)
        : {ticks: zrUtil.map(axis.scale.getTicks(), tick => tick.value) };
}

/**
 * Parse the user specified `customValues` to the inner tick values
 * (the ordinal number for ordinal scale, the numeric value otherwise),
 * and discard the values that are out of the axis extent.
 */
function parseCustomValues(axis: Axis, customValues: (number | string | Date)[]): number[] {
    const scale = axis.scale;
    const extent = scale.getExtent();
    const result: number[] = [];
    zrUtil.each(customValues, function (val) {
        const tickValue = scale.parse(val);
        // NaN is filtered out by the comparison as well.
        if (tickValue >= extent[0] && tickValue <= extent[1]) {
            result.push(tickValue);
        }
    });
    return result;
}

/**
 * Make labels at the `axisLabel.customValues` if specified,
 * otherwise return `null` to keep the default behavior.
 */
function makeAxisLabelsFromCustomValues(axis: Axis): ReturnType<typeof createAxisLabels> {
    const labelModel = axis.getLabelModel();
    const customValues = labelModel.get('customValues');
    if (!customValues) {
        return null;
    }
    // Labels are always made by the normal label formatter, so that,
    // for example, time axis labels are formatted as expected.
    const labelFormatter = makeLabelFormatter(axis);
    return {
        labels: zrUtil.map(parseCustomValues(axis, customValues), function (tickValue, idx) {
            const tickObj = { value: tickValue };
            return {
                formattedLabel: labelFormatter(tickObj, idx),
                rawLabel: axis.scale.getLabel(tickObj),
                tickValue: tickValue
            };
        })
    };
}

function makeCategoryLabels(axis: Axis) {
    const labelModel = axis.getLabelModel();
    const result = makeCategoryLabelsActually(axis, labelModel);

    return (!labelModel.get('show') || axis.scale.isBlank())
        ? {labels: [], labelCategoryInterval: result.labelCategoryInterval}
        : result;
}

function makeCategoryLabelsActually(axis: Axis, labelModel: Model<AxisBaseOption['axisLabel']>) {
    const labelsCache = getListCache(axis, 'labels');
    const scaleExtent = axis.scale.getExtent();
    const optionLabelInterval = getOptionCategoryInterval(labelModel);
    const result = listCacheGet(labelsCache, optionLabelInterval as CacheKey, scaleExtent);

    if (result) {
        return result;
    }

    let labels;
    let numericLabelInterval;

    if (zrUtil.isFunction(optionLabelInterval)) {
        labels = makeLabelsByCustomizedCategoryInterval(axis, optionLabelInterval);
    }
    else {
        numericLabelInterval = optionLabelInterval === 'auto'
            ? makeAutoCategoryInterval(axis) : optionLabelInterval;
        labels = makeLabelsByNumericCategoryInterval(axis, numericLabelInterval);
    }

    // Cache to avoid calling interval function repeatedly.
    return listCacheSet(labelsCache, optionLabelInterval as CacheKey, scaleExtent, {
        labels: labels, labelCategoryInterval: numericLabelInterval
    });
}

function makeCategoryTicks(axis: Axis, tickModel: AxisBaseModel) {
    const ticksCache = getListCache(axis, 'ticks');
    const scaleExtent = axis.scale.getExtent();
    const optionTickInterval = getOptionCategoryInterval(tickModel);
    const result = listCacheGet(ticksCache, optionTickInterval as CacheKey, scaleExtent);

    if (result) {
        return result;
    }

    let ticks: number[];
    let tickCategoryInterval;

    // Optimize for the case that large category data and no label displayed,
    // we should not return all ticks.
    if (!tickModel.get('show') || axis.scale.isBlank()) {
        ticks = [];
    }

    if (zrUtil.isFunction(optionTickInterval)) {
        ticks = makeLabelsByCustomizedCategoryInterval(axis, optionTickInterval, true);
    }
    // Always use label interval by default despite label show. Consider this
    // scenario, Use multiple grid with the xAxis sync, and only one xAxis shows
    // labels. `splitLine` and `axisTick` should be consistent in this case.
    else if (optionTickInterval === 'auto') {
        const labelsResult = makeCategoryLabelsActually(axis, axis.getLabelModel());
        tickCategoryInterval = labelsResult.labelCategoryInterval;
        ticks = zrUtil.map(labelsResult.labels, function (labelItem) {
            return labelItem.tickValue;
        });
    }
    else {
        tickCategoryInterval = optionTickInterval;
        ticks = makeLabelsByNumericCategoryInterval(axis, tickCategoryInterval, true);
    }

    // Cache to avoid calling interval function repeatedly.
    return listCacheSet(ticksCache, optionTickInterval as CacheKey, scaleExtent, {
        ticks: ticks, tickCategoryInterval: tickCategoryInterval
    });
}

function makeRealNumberLabels(axis: Axis) {
    const ticks = axis.scale.getTicks();
    const labelFormatter = makeLabelFormatter(axis);
    return {
